import { LhkpnFileSchema } from '@jaga-daerah/contracts';

import lhkpnJson from '@/data/lhkpn.json';

// Generated by `uv run python -m jaga_etl.lhkpn build` from pages a human saved by hand from KPK's
// e-Announcement search; parsed at build time so a malformed file fails the build. Empty until a
// capture exists — a region with no entry renders "belum tersedia" instead of a figure.
export const LHKPN = LhkpnFileSchema.parse(lhkpnJson);
